#pragma once
#include <string>
#include <string_view>

// Shared, self-contained shell: the LAN controller never needs a font or script CDN.
namespace webui {
inline std::string styles() {
    return R"CSS(
:root{color-scheme:dark;--bg:#10191e;--surface:#18242b;--surface-soft:#1e2e35;--ink:#edf5f3;--muted:#a5b9ba;--line:#314249;--accent:#65dfc3;--accent-ink:#0b3027;--warning:#ffd29a;--danger:#ffb7b0;--shadow:0 10px 30px #0002;--radius:22px}
:root[data-theme=light]{color-scheme:light;--bg:#f2f5f2;--surface:#fff;--surface-soft:#edf3ef;--ink:#172c2a;--muted:#536d68;--line:#d7e2dc;--accent:#137d65;--accent-ink:#fff;--warning:#895316;--danger:#ac302b;--shadow:0 8px 25px #163c2310}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;-webkit-text-size-adjust:100%}a{color:var(--accent);text-decoration:none}button,input,select,textarea{font:inherit}button,a,input,select,textarea{touch-action:manipulation}button,.button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 16px;border:1px solid var(--line);border-radius:12px;background:var(--surface-soft);color:var(--ink);font-size:14px;font-weight:650;cursor:pointer;text-align:center;text-decoration:none}button:hover,.button:hover{border-color:var(--accent)}button:disabled{opacity:.5;cursor:default}.primary,.button.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}.quiet{background:transparent}.danger{color:var(--danger)}:focus-visible{outline:3px solid var(--accent);outline-offset:4px}input:not([type=checkbox]):not([type=color]):not([type=range]),select,textarea{width:100%;min-width:0;min-height:46px;border:1px solid var(--line);border-radius:11px;background:var(--bg);color:var(--ink);padding:10px 12px;font-size:16px}textarea{resize:vertical}input[type=checkbox]{width:20px;height:20px;accent-color:var(--accent);flex-shrink:0}input[type=range]{width:100%;min-width:0;min-height:44px;accent-color:var(--accent)}input[type=color]{width:46px;height:44px;padding:3px;border:1px solid var(--line);background:var(--bg);border-radius:10px}label{font-size:13px;font-weight:650;color:var(--muted);display:block;margin-bottom:7px}h1,h2,h3,p{margin:0}h1{font-size:clamp(27px,3.2vw,38px);font-weight:750;letter-spacing:-1.1px;line-height:1.15}h2{font-size:19px;letter-spacing:-.35px}h3{font-size:16px}p{color:var(--muted)}small,.hint{font-size:13px;color:var(--muted)}.icon{width:20px;height:20px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.app-shell{max-width:1288px;padding:0 28px;margin:auto}.site-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:26px 0 22px}.brand{display:flex;gap:11px;align-items:center;color:var(--ink)}.brand-mark{display:grid;place-items:center;background:var(--accent);color:var(--accent-ink);width:43px;height:43px;border-radius:14px}.brand-name{font-weight:800;font-size:22px;letter-spacing:-.7px}.brand-caption{display:block;color:var(--muted);font-size:11px;letter-spacing:1.6px;text-transform:uppercase}.utilities{display:flex;align-items:center;justify-content:flex-end;gap:10px;flex-wrap:wrap}.utilities label{margin:0}.utilities select{font-size:13px;min-height:40px;padding:8px 28px 8px 10px;width:auto}.icon-button{width:44px;padding:10px}.connection{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:12px}.connection:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--warning)}.connection[data-state=online]:before{background:var(--accent)}.connection[data-state=offline]:before{background:var(--danger)}.app-nav{display:flex;align-items:center;gap:6px;border-bottom:1px solid var(--line);padding-bottom:14px;margin-bottom:28px}.nav-link{display:flex;align-items:center;justify-content:center;gap:9px;color:var(--muted);font-size:14px;font-weight:650;padding:12px 20px;min-height:46px;border-radius:12px}.nav-link:hover{background:var(--surface-soft);color:var(--ink)}.nav-link[aria-current=page]{background:var(--surface-soft);color:var(--accent)}.page-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:25px}.page-heading p{font-size:14px;margin-top:10px}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:1.8px;font-weight:750;color:var(--accent);margin-bottom:9px}.card{min-width:0;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow)}.card-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px}.card-heading p{font-size:13px;margin-top:4px}.stack{display:grid;gap:20px;align-content:start}.row{display:flex;align-items:center;gap:12px}.row.wrap{flex-wrap:wrap}.grow{flex:1;min-width:0}.grid,.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.field{min-width:0;margin-bottom:18px}.toggle,.check-label{display:flex;align-items:center;gap:11px;min-height:44px;color:var(--ink);font-size:14px;font-weight:550;margin:0;cursor:pointer}.toggle small{display:block;font-weight:400;font-size:12px}.notice{color:var(--danger);border:1px solid var(--danger);background:var(--surface);border-radius:14px;padding:14px 17px;margin-bottom:20px;font-size:14px;white-space:pre-wrap;overflow-wrap:anywhere}.status{color:var(--muted);font-size:13px;min-height:22px}.badge{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;letter-spacing:.3px;border-radius:7px;padding:4px 8px;background:var(--surface-soft);color:var(--accent);border:1px solid var(--line)}.empty{padding:30px 12px;text-align:center;color:var(--muted);font-size:14px}.site-footer{display:flex;justify-content:space-between;gap:16px;padding:26px 0 32px;font-size:12px;color:var(--muted)}.access-card{max-width:680px;margin-bottom:24px}.access-card h2{margin-bottom:7px}.access-card p{font-size:13px;margin-bottom:18px}.access-card .row{align-items:stretch}.toast{position:fixed;z-index:30;bottom:24px;left:50%;transform:translate(-50%,20px);max-width:min(540px,calc(100vw - 32px));background:var(--ink);color:var(--bg);border-radius:13px;padding:13px 20px;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s;font-size:14px;box-shadow:var(--shadow)}.toast.show{opacity:1;transform:translate(-50%,0)}.skip-link{position:absolute;top:-80px;left:20px;z-index:100;background:var(--accent);color:var(--accent-ink);padding:12px;border-radius:10px}.skip-link:focus{top:10px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}[hidden]{display:none!important}main{min-width:0}code{font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}
@media(max-width:760px){.app-shell{padding:0 16px}.site-header{padding:19px 0 24px;gap:10px}.brand-caption{display:none}.brand-name{font-size:20px}.brand-mark{width:38px;height:38px;border-radius:12px}.utilities{gap:7px}.connection{position:absolute;top:69px;right:17px;font-size:11px}.utilities select{font-size:12px;min-height:38px;max-width:95px}.utilities .icon-button{width:38px;min-height:38px;padding:8px}.app-nav{position:fixed;z-index:20;bottom:max(10px,env(safe-area-inset-bottom));left:12px;right:12px;margin:0;padding:6px;background:var(--surface);border:1px solid var(--line);border-radius:20px;box-shadow:0 8px 40px #0004;gap:2px}.nav-link{flex:1;min-width:0;flex-direction:column;gap:4px;padding:8px 2px;font-size:10px;min-height:56px;border-radius:14px}.nav-link .icon{width:20px;height:20px}.page-heading{margin:22px 0;align-items:flex-start}.page-heading p{font-size:13px}.card{padding:19px;border-radius:19px}.stack{gap:16px}.grid,.form-grid{grid-template-columns:minmax(0,1fr);gap:0}.site-footer{padding-bottom:108px;flex-wrap:wrap;font-size:11px}.toast{bottom:calc(93px + env(safe-area-inset-bottom))}.access-card .row{flex-wrap:wrap}.access-card .row input{flex-basis:100%}.access-card .row button{flex:1}.page-heading .button{font-size:12px;padding:9px 12px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
)CSS";
}
inline std::string script() {
    return R"JS(<script>
'use strict';
window.FrameUI=(()=>{
 const $=id=>document.getElementById(id), read=(key)=>{try{return localStorage.getItem(key);}catch{return null;}},write=(key,value)=>{try{localStorage.setItem(key,value);}catch{}};
 const system=matchMedia('(prefers-color-scheme: light)');let appearance=read('pitrove-appearance')||(read('pitrove-theme')==='light-theme'?'light':'system'),locked=false,unlocked=()=>{},toastTimer;
 if(!['system','light','dark'].includes(appearance))appearance='system';
 function applyTheme(){document.documentElement.dataset.theme=appearance==='system'?(system.matches?'light':'dark'):appearance;}
 applyTheme();system.addEventListener('change',applyTheme);
 function connection(online){const node=$('connection');if(node){node.dataset.state=online?'online':'offline';node.textContent=online?'Connected to frame':'Reconnecting…';}}
 function toast(message){const node=$('toast');node.textContent=message;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),3500);}
 function access(){if($('unlock')){$('unlock').hidden=false;$('api-key').focus();}}
 async function request(path,options={}){
  if(locked&&options.protected!==false&&!options.key){const e=Error('Unlock your controller with its access key.');e.status=401;throw e;}
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),options.timeout||12000),headers={},key=options.key||read('api_key');if(key)headers.Authorization='Bearer '+key;
  const settings={headers,cache:'no-store',signal:controller.signal,credentials:'same-origin'};
  if(options.fields!==undefined){settings.method='POST';settings.body=new URLSearchParams(options.fields);headers['Content-Type']='application/x-www-form-urlencoded';}else if(options.method)settings.method=options.method;
  try{const response=await fetch(path,settings);if(response.status===401){locked=true;access();}
   if(!response.ok){let detail='';try{const text=await response.text();try{const data=JSON.parse(text);detail=data.error||data.message||'';}catch{detail=text;}}catch{}
    const error=Error(response.status===401?'Enter your controller access key to continue.':response.status===429?'Give the frame a moment, then try again.':detail||'The frame could not complete that request.');error.status=response.status;throw error;}
   if(options.blob)return await response.blob();return await response.json();
  }catch(e){if(e.name==='AbortError')throw Error('The frame took too long to respond. Please try again.');throw e;}finally{clearTimeout(timer);}
 }
 function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
 function init(){const select=$('appearance');select.value=appearance;select.addEventListener('change',()=>{appearance=select.value;write('pitrove-appearance',appearance);applyTheme();});$('sign-out').hidden=!read('api_key');$('sign-out').addEventListener('click',()=>{setKey('');write('pitrove-signed-out','1');location.reload();});if(read('pitrove-signed-out')){try{localStorage.removeItem('pitrove-signed-out');}catch{}access();}$('access-button').addEventListener('click',()=>{if($('unlock').hidden)access();else $('unlock').hidden=true;});$('unlock').addEventListener('submit',async e=>{e.preventDefault();const button=$('unlock-submit');button.disabled=true;try{await request('/api/settings',{key:$('api-key').value,timeout:15000});setKey($('api-key').value);$('api-key').value='';$('unlock').hidden=true;$('unlock-error').textContent='';toast('Controller unlocked.');await unlocked();}catch(err){$('unlock-error').textContent=err.message;}finally{button.disabled=false;}});window.addEventListener('storage',e=>{if(e.key==='pitrove-appearance'){appearance=read('pitrove-appearance')||'system';select.value=appearance;applyTheme();}if(e.key==='api_key'){if(!e.newValue&&e.oldValue)location.reload();else {$('sign-out').hidden=!e.newValue;locked=false;}}});}
 document.addEventListener('DOMContentLoaded',init);
 function setKey(value){try{if(value)localStorage.setItem('api_key',value);else localStorage.removeItem('api_key');}catch{}locked=false;if($('sign-out'))$('sign-out').hidden=!value;}
 return {$,request,toast,connection,download,setKey,onUnlock:fn=>{unlocked=fn;},access};
})();
</script>)JS";
}
inline std::string start(std::string_view title, std::string_view active) {
    std::string html="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"color-scheme\" content=\"dark light\"><meta name=\"theme-color\" content=\"#10191e\"><title>"+std::string(title)+" · piTrove</title><style>"+styles()+"</style>"+script()+R"SHELL(</head><body>
<svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true"><symbol id="i-frame" viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="3"/><path d="m5 17 5-6 4 4 3-3 4 5"/><circle cx="16" cy="8" r="1"/></symbol><symbol id="i-home" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="13" rx="3"/><path d="M8 21h8m-4-4v4"/></symbol><symbol id="i-check" viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="5"/><path d="m7 12 3 3 7-7"/></symbol><symbol id="i-settings" viewBox="0 0 24 24"><path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/></symbol><symbol id="i-activity" viewBox="0 0 24 24"><path d="M3 12h4l3-8 4 16 3-8h4"/></symbol><symbol id="i-key" viewBox="0 0 24 24"><circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-5-5 3-3m-6 0 3-3"/></symbol><symbol id="i-prev" viewBox="0 0 24 24"><path d="M5 5v14m14-14L8 12l11 7z"/></symbol><symbol id="i-next" viewBox="0 0 24 24"><path d="M19 5v14M5 5l11 7-11 7z"/></symbol><symbol id="i-camera" viewBox="0 0 24 24"><path d="M3 7h4l2-3h6l2 3h4v14H3z"/><circle cx="12" cy="13" r="4"/></symbol></svg>
<a class="skip-link" href="#main">Skip to content</a><div class="app-shell"><header class="site-header"><a class="brand" href="/#remote" aria-label="piTrove home"><span class="brand-mark"><svg class="icon" aria-hidden="true"><use href="#i-frame"/></svg></span><span><span class="brand-name">piTrove</span><span class="brand-caption">Your home, in view</span></span></a><div class="utilities"><span id="connection" class="connection" role="status" data-state="connecting">Connecting…</span><label><span class="sr-only">Appearance</span><select id="appearance"><option value="system">Auto theme</option><option value="light">Light</option><option value="dark">Dark</option></select></label><button type="button" id="sign-out" class="quiet" hidden>Sign out</button><button id="access-button" class="icon-button quiet" aria-label="Controller access key" title="Controller access key"><svg class="icon" aria-hidden="true"><use href="#i-key"/></svg></button></div></header><nav class="app-nav" aria-label="Main navigation">
)SHELL";
    struct Nav { const char* id; const char* href; const char* icon; const char* text; };
    for(const auto& n : {Nav{"remote","/#remote","home","Frame"},Nav{"chores","/chores","check","Chores"},Nav{"settings","/config","settings","Settings"},Nav{"logs","/#logs","activity","Activity"}}) {
        html+="<a class=\"nav-link\" data-page=\""+std::string(n.id)+"\" href=\""+n.href+"\""+(active==n.id?" aria-current=\"page\"":"")+"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-"+n.icon+"\"/></svg><span>"+n.text+"</span></a>";
    }
    return html+R"SHELL(</nav><main id="main" tabindex="-1"><form id="unlock" class="card access-card" hidden><h2>Unlock your controller</h2><p>Enter the access key configured for your frame. It is remembered in this browser.</p><label for="api-key">Controller access key</label><div class="row"><input id="api-key" class="grow" type="password" autocomplete="current-password" required><button id="unlock-submit" class="primary">Unlock</button></div><p id="unlock-error" role="alert" class="danger" style="margin:10px 0 0"></p></form>)SHELL";
}
inline std::string end(std::string_view version) {
    return "</main><footer class=\"site-footer\"><span>piTrove "+std::string(version)+"</span><span>Made for the moments at home.</span></footer></div><div id=\"toast\" class=\"toast\" role=\"status\" aria-live=\"polite\"></div></body></html>";
}
} // namespace webui
